CustomField.description:
FORMULA_PENDING | Original: IF(
  AND(
    RecordType.DeveloperName = &quot;Surgeries&quot;,
    NOT(ISBLANK(ReceiptNum__c)),
    ISPICKVAL(Status_private_room__c, &quot;Canceled&quot;)
  ),
  IF(
    (Appointment_Date_Time__c - Cancellation_Date_Time_Private_Rooms__c) * 24 &gt;= 24,
    &quot;🟢 זיכוי מלא&quot;,
    IF(
      (Appointment_Date_Time__c - Cancellation_Date_Time_Private_Rooms__c) * 24 &gt;= 12,
      &quot;🟡 זיכוי 50%&quot;,
      IF(
        (Appointment_Date_Time__c - Cancellation_Date_Time_Private_Rooms__c) * 24 &gt;= 4,
        &quot;🔴 לא זכאי&quot;,
        &quot;🔴 לא זכאי&quot;
      )
    )
  ),
  &quot;&quot;
)
